/**
 * Framework dimension -> directory categories that tend to exercise it.
 * A dimension with no strong mapping falls back to a spread of the directory,
 * so the caller always gets something rather than an empty list.
 */
const DIMENSION_CATEGORIES = {
  'social-object':     ['Social marketplace', 'Creator platform', 'Events', 'Location'],
  'identity':          ['Dating', 'Creator platform', 'Networking', 'Community'],
  'conversations':     ['Messaging', 'Forum', 'Community'],
  'sharing':           ['Video sharing', 'Creator platform', 'Social marketplace'],
  'presence':          ['Location', 'Messaging', 'Events'],
  'relationships':     ['Networking', 'Dating', 'Community', 'Groups'],
  'reputation':        ['Social marketplace', 'Forum', 'Community'],
  'groups':            ['Groups', 'Forum', 'Community'],
  'agency':            ['Community', 'Groups', 'Bundled'],
  'enable-dimension':  ['Community', 'Groups'],
  'grow-dimension':    ['Social marketplace', 'Creator platform', 'Bundled'],
  'protect-dimension': ['Community', 'Forum', 'Dating'],
};

/**
 * A handful of directory platforms relevant to a dimension.
 *
 * Ranked by how specifically a platform matches: the first category listed for
 * a dimension scores highest, so "groups" surfaces actual Groups and Forum
 * platforms ahead of the 205 generic "Community" ones. Without this weighting
 * every dimension returned the same alphabetically-first Community entries.
 *
 * Countries are then spread, since the UK and Germany hold a third of the
 * directory between them and would otherwise crowd out everywhere else.
 */
export function platformsForConcept(conceptId, limit = 6) {
  const wanted = DIMENSION_CATEGORIES[conceptId] || [];

  const score = (p) => {
    let best = 0;
    p.categories.forEach(c => {
      const rank = wanted.indexOf(c);
      if (rank !== -1) best = Math.max(best, wanted.length - rank);
    });
    return best;
  };

  // Ties are broken by a hash of dimension + platform name. Without it,
  // dimensions sharing a top category (identity and relationships both lead
  // with Dating) returned byte-identical lists, which made the examples look
  // canned. The hash is stable, so the same dimension always shows the same
  // platforms — it varies between dimensions, not between runs.
  const salt = (name) => {
    let h = 0;
    const key = conceptId + '|' + name;
    for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) | 0;
    return h;
  };

  const pool = (wanted.length ? REBUILD_DIRECTORY.filter(p => score(p) > 0) : REBUILD_DIRECTORY)
    .slice()
    .sort((a, b) => (score(b) - score(a)) || (salt(a.name) - salt(b.name)));

  const source = pool.length ? pool : REBUILD_DIRECTORY;

  const picked = [];
  const usedCountries = new Set();
  for (const p of source) {
    if (picked.length >= limit) break;
    if (p.country && usedCountries.has(p.country)) continue;
    usedCountries.add(p.country);
    picked.push(p);
  }
  for (const p of source) {
    if (picked.length >= limit) break;
    if (!picked.includes(p)) picked.push(p);
  }
  return picked;
}

/** Compact lines for a prompt — name, country, what it is. */
export function directoryLines(conceptId, limit = 6) {
  return platformsForConcept(conceptId, limit)
    .map(p => `- ${p.name} (${p.country}) — ${p.description}`)
    .join('\n');
}

/**
 * Name/url pairs for the platforms offered in one turn, so the reply can link
 * only those. Linking against the whole directory would be wrong: it contains
 * entries called Adam, Done, Village and Bump, and those words appear in
 * ordinary prose.
 */
export function linkablePlatforms(conceptId, limit = 6) {
  return platformsForConcept(conceptId, limit).map(p => ({ name: p.name, url: p.url }));
}
